import{_ as r,o as d,c as a,a2 as e}from"./chunks/framework.CRFziyHp.js";const b=JSON.parse('{"title":"页面类型说明","description":"","frontmatter":{},"headers":[],"relativePath":"features/ui-editor/page-types.md","filePath":"features/ui-editor/page-types.md","lastUpdated":1785013113000}'),o={name:"features/ui-editor/page-types.md"};function s(n,t,i,l,h,g){return d(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="页面类型说明" tabindex="-1">页面类型说明 <a class="header-anchor" href="#页面类型说明" aria-label="Permalink to &quot;页面类型说明&quot;">​</a></h1><p>在 <strong>UI管理 → 页面配置</strong> 中，每种 <strong>页面类型</strong> 对应客户端的不同位置，且 <strong>可用组件不同</strong>。</p><p>新建页面时在弹窗中选择类型；列表左侧可按类型筛选。</p><h2 id="类型总览" tabindex="-1">类型总览 <a class="header-anchor" href="#类型总览" aria-label="Permalink to &quot;类型总览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类型</th><th>列表名称</th><th>客户端位置</th><th>编辑方式</th></tr></thead><tbody><tr><td><code>home</code></td><td>应用首页</td><td>底部 Tab <strong>首页</strong></td><td>可视化画布</td></tr><tr><td><code>feature</code></td><td>功能页面</td><td>底部 Tab <strong>发现/圈子</strong> 等</td><td>可视化画布</td></tr><tr><td><code>profile</code></td><td>个人中心</td><td><strong>我的</strong> Tab 内个人中心</td><td>面板配置页</td></tr><tr><td><code>news</code></td><td>消息中心</td><td><strong>消息</strong> Tab</td><td>面板配置页</td></tr><tr><td><code>settings</code></td><td>设置中心</td><td>设置页</td><td>面板配置页</td></tr><tr><td><code>user_guidance</code></td><td>用户引导</td><td>新用户引导流程</td><td>面板配置页</td></tr><tr><td><code>official_intro</code></td><td>官网介绍</td><td>全站介绍页</td><td>面板配置页</td></tr><tr><td><code>custom</code></td><td>自定义页面</td><td>独立页面，需自行配置跳转</td><td>可视化画布</td></tr><tr><td><code>forum</code></td><td>社区圈子</td><td>单个圈子详情页</td><td>可视化画布 + 头区配置</td></tr><tr><td><code>errand_service</code></td><td>服务表单</td><td>跑腿等服务下单页</td><td>可视化画布（仅表单组件）</td></tr></tbody></table><hr><h2 id="tab-页面" tabindex="-1">Tab 页面 <a class="header-anchor" href="#tab-页面" aria-label="Permalink to &quot;Tab 页面&quot;">​</a></h2><h3 id="应用首页-home" tabindex="-1">应用首页（home） <a class="header-anchor" href="#应用首页-home" aria-label="Permalink to &quot;应用首页（home）&quot;">​</a></h3><ul><li>用户打开 App 默认看到的 <strong>第一个 Tab 页</strong></li><li>可用除「表单/服务」外的 <strong>全部内容组件</strong></li><li>常与 <strong>筛选标签 + 笔记列表</strong> 组合</li></ul><h3 id="功能页面-feature" tabindex="-1">功能页面（feature） <a class="header-anchor" href="#功能页面-feature" aria-label="Permalink to &quot;功能页面（feature）&quot;">​</a></h3><ul><li>第二个 Tab 常用作 <strong>发现页 / 圈子广场</strong></li><li>组件规则与首页相同</li><li>在 <strong>TabBar 配置</strong> 中绑定到对应 Tab 路由</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>首页与功能页都通过 <strong>TabBar</strong> 进入，但 UI 配置 <strong>分开保存</strong>。改首页不会自动改功能页。</p></div><hr><h2 id="面板配置页" tabindex="-1">面板配置页 <a class="header-anchor" href="#面板配置页" aria-label="Permalink to &quot;面板配置页&quot;">​</a></h2><p>以下类型 <strong>不进入三栏画布</strong>，而是专用 <strong>配置表单</strong>（列表卡片上按钮为 <strong>配置</strong>）：</p><table tabindex="0"><thead><tr><th>类型</th><th>主要配置内容</th></tr></thead><tbody><tr><td><strong>个人中心</strong></td><td>用户头像区样式、功能卡片列表、菜单入口</td></tr><tr><td><strong>消息中心</strong></td><td>消息 Tab 结构、订阅消息入口卡片</td></tr><tr><td><strong>设置中心</strong></td><td>设置项分组与跳转链接</td></tr><tr><td><strong>用户引导</strong></td><td>引导步骤文案与图片</td></tr><tr><td><strong>官网介绍</strong></td><td>介绍页模块与文案</td></tr></tbody></table><p>保存后同样在列表中 <strong>启用</strong> 才对用户生效。</p><hr><h2 id="独立页面" tabindex="-1">独立页面 <a class="header-anchor" href="#独立页面" aria-label="Permalink to &quot;独立页面&quot;">​</a></h2><h3 id="自定义页面-custom" tabindex="-1">自定义页面（custom） <a class="header-anchor" href="#自定义页面-custom" aria-label="Permalink to &quot;自定义页面（custom）&quot;">​</a></h3><ul><li>独立分包页面，不占用 Tab 位</li><li>需通过 <strong>金刚区、按钮、TabBar、通知</strong> 等配置 <strong>点击动作</strong> 跳转到该页</li><li>客户端路径形如：<code>/pages_user/custom-page/index?page_type=你的页面类型标识</code></li><li>新建时系统会生成唯一 <code>page_type</code>（如 <code>custom_xxx</code>）</li></ul><p><strong>适用</strong>：活动页、专题页、静态介绍页。</p><h3 id="社区圈子-forum" tabindex="-1">社区圈子（forum） <a class="header-anchor" href="#社区圈子-forum" aria-label="Permalink to &quot;社区圈子（forum）&quot;">​</a></h3><p>圈子详情页的 UI，包含两部分：</p><p><strong>1. 左侧组件库 — 圈子专属（非画布组件）</strong></p><table tabindex="0"><thead><tr><th>配置项</th><th>选项</th><th>作用</th></tr></thead><tbody><tr><td>头区布局</td><td>默认 / 居中 / 卡片</td><td>圈子顶部封面与信息排版</td></tr><tr><td>动态列表卡片模板</td><td>模板 1 / 2 / 3</td><td>帖子的展示样式</td></tr><tr><td>跟随首页</td><td>是 / 否</td><td>列表样式是否与首页笔记列表一致</td></tr></tbody></table><p><strong>2. 画布可添加组件</strong></p><p>仅 <strong>筛选标签</strong> + <strong>笔记列表</strong>（与首页相比，筛选联动目标固定为笔记）。</p><h3 id="服务表单-errand-service" tabindex="-1">服务表单（errand_service） <a class="header-anchor" href="#服务表单-errand-service" aria-label="Permalink to &quot;服务表单（errand_service）&quot;">​</a></h3><p>用于 <strong>跑腿下单、可配置服务</strong> 等场景：</p><ul><li>组件库 <strong>仅显示表单/服务</strong> 16 个组件</li><li>隐藏轮播、社区、榜单等内容组件</li><li>必须包含 <strong>提交底栏</strong>（每页唯一，固定吸底）</li><li>右侧额外 <strong>服务表单</strong> Tab：履约模式、计价公式、模板编码等</li></ul><p>需配合 <a href="/features/errand">跑腿</a> 业务与区域配置使用。</p><hr><h2 id="各类型可用组件对照" tabindex="-1">各类型可用组件对照 <a class="header-anchor" href="#各类型可用组件对照" aria-label="Permalink to &quot;各类型可用组件对照&quot;">​</a></h2><table tabindex="0"><thead><tr><th>组件分类</th><th>home / feature / custom</th><th>forum</th><th>errand_service</th></tr></thead><tbody><tr><td>基础元素</td><td>✅（按钮在表单页隐藏）</td><td>✅</td><td>❌ 仅表单内按钮</td></tr><tr><td>布局导航</td><td>✅</td><td>仅筛选标签</td><td>❌</td></tr><tr><td>信息展示</td><td>✅（结束文本在表单页隐藏）</td><td>✅</td><td>❌</td></tr><tr><td>社区内容</td><td>✅</td><td>仅笔记列表</td><td>❌</td></tr><tr><td>运营模块</td><td>✅</td><td>❌</td><td>❌</td></tr><tr><td>表单/服务</td><td>❌</td><td>❌</td><td>✅ 全部</td></tr></tbody></table><hr><h2 id="互斥与唯一性规则" tabindex="-1">互斥与唯一性规则 <a class="header-anchor" href="#互斥与唯一性规则" aria-label="Permalink to &quot;互斥与唯一性规则&quot;">​</a></h2><p>以下规则在编辑器中自动限制（重复添加会提示或置灰）：</p><table tabindex="0"><thead><tr><th>规则</th><th>说明</th></tr></thead><tbody><tr><td>筛选标签</td><td>每页 <strong>最多 1 个</strong></td></tr><tr><td>圈子列表 / 笔记列表 / 瀑布流</td><td><strong>三选一</strong>，每页最多 1 个</td></tr><tr><td>提交底栏</td><td>服务表单页 <strong>最多 1 个</strong></td></tr><tr><td>表单组件</td><td>仅 <strong>服务表单</strong> 页可添加</td></tr></tbody></table><hr><h2 id="与-tabbar-的关系" tabindex="-1">与 TabBar 的关系 <a class="header-anchor" href="#与-tabbar-的关系" aria-label="Permalink to &quot;与 TabBar 的关系&quot;">​</a></h2><ul><li><strong>TabBar</strong> 决定底部有几个 Tab、图标与跳转路由</li><li><strong>页面配置</strong> 决定用户进入该 Tab 后看到的内容</li><li>两者 <strong>按区域分别存储</strong>，需分别保存</li></ul><p>示例：TabBar 第二个 Tab 指向发现页路由 → 编辑 <strong>功能页面（feature）</strong> 类型的 UI → 分别 <strong>保存</strong> 并 <strong>启用</strong>。</p><p>详见 <a href="/features/ui-editor/tabbar">TabBar 配置</a>。</p><hr><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="/features/ui-editor/styles-and-actions">样式与点击动作</a></li><li><a href="/features/ui-editor/components-basic">组件手册 — 基础元素</a></li><li><a href="/features/ui-editor/components-form">表单组件</a></li></ul>',47)])])}const u=r(o,[["render",s]]);export{b as __pageData,u as default};
